bool ddsi_typeid_is_minimal_impl (const struct DDS_XTypes_TypeIdentifier *type_id);

/** @component xtypes_wrapper */
bool ddsi_typeid_is_complete_impl (const struct DDS_XTypes_TypeIdentifier *type_id);

